opencat.script:
var T = ctx.timeline();
// Each clip + caption owns a [start, start+dur) window. The reference
// hard-cuts between clips (no cross-fade), and `.cap` plays the CSS
// `cap-pop` keyframes when it appears.
var CAP_EASE = [0.34, 1.56, 0.64, 1];
// Bottom `.cap` windows come from the reference master (index.html
// data-start/data-duration, minus act3's 12.0s offset): they are shorter
// than the clip and start slightly after it. The top-left `.a3-cap`
// (c01..c11) instead spans the whole clip like its video.
var CLIPS = [
  ['v01', 'c01', 0.0,  1.500],
  ['v02', 'c02', 1.5,  1.917],
  ['v03', 'c03', 3.4,  2.000],
  ['v04', 'c04', 5.4,  1.800],
  ['v05', 'c05', 7.2,  2.000],
  ['v06', 'c06', 9.2,  2.000],
  ['v07', 'c07', 11.2, 2.000],
  ['v08', 'c08', 13.2, 2.000],
  ['v09', 'c09', 15.2, 3.000],
  ['v10', 'c10', 18.2, 1.608],
  ['v11', 'c11', 19.8, 2.000],
];
var MCAP = [
  [0.20, 1.25], [1.70, 1.35], [3.60, 1.02], [5.60, 0.98],
  [7.40, 1.35], [9.40, 1.16], [11.40, 1.21], [13.40, 1.16],
  [15.40, 1.30], [18.25, 1.50], [19.80, 0.80],
];
for (var i = 0; i < CLIPS.length; i++) {
  var v = CLIPS[i][0], c = CLIPS[i][1], at = CLIPS[i][2], dur = CLIPS[i][3];
  // Video: hard cut in, hard cut out — the clip's own media window is
  // already bounded by data-start/data-duration.
  T.set(v, { opacity: 1 }, at);
  T.set(v, { opacity: 0 }, at + dur);
  // Top-left `.a3-cap` card: NO entrance animation in the reference (the
  // `.a3-cap` rule has no `animation` and no GSAP targets it) — it is
  // statically visible from the clip's first frame, unlike the bottom
  // `.cap` which runs `cap-pop`. opencat previously popped it in, leaving
  // the card absent at f0..~7 of every clip.
  T.set(c, { opacity: 1 }, at);
  T.set(c, { opacity: 0 }, at + dur);
  // Master bottom caption (its own shorter VO window).
  var m = 'm' + (i < 9 ? '0' : '') + (i + 1);
  var mAt = MCAP[i][0], mDur = MCAP[i][1];
  T.set(m, { opacity: 0, y: 18, scale: 0.82 }, mAt);
  T.to(m, { opacity: 1, y: -2, scale: 1.04, duration: 0.182, ease: CAP_EASE }, mAt);
  T.to(m, { y: 0, scale: 1.0, duration: 0.078, ease: CAP_EASE }, mAt + 0.182);
  T.set(m, { opacity: 0 }, mAt + mDur);
}
